def coveredAfterEach(intervals):
    xs = sorted({x for iv in intervals for x in iv})
    idx = {x: i for i, x in enumerate(xs)}
    nxt = list(range(len(xs)))

    def find(i):
        root = i
        while nxt[root] != root:
            root = nxt[root]
        while nxt[i] != root:
            nxt[i], i = root, nxt[i]
        return root

    total = 0
    res = []
    for s, e in intervals:
        hi = idx[e]
        i = find(idx[s])
        while i < hi:
            total += xs[i + 1] - xs[i]
            nxt[i] = i + 1
            i = find(i + 1)
        res.append(total)
    return res
